-- Existing receiving batch identity across stock reports. No receipt/IMEI history is renumbered.
begin;
do $$begin if public.get_parts_supplier_codes_version()is distinct from '20261027-parts-supplier-codes-1'then raise exception 'Verified Parts Supplier Codes are required.';end if;if to_regprocedure('public.get_stock_batch_links_version()')is not null then if public.get_stock_batch_links_version()is distinct from '20261027-stock-batches-1'then raise exception 'Existing stock batch support needs review.';end if;end if;end;$$;
create or replace function greenloop_private.sb_returns()returns table(id uuid,order_id uuid,legacy boolean,imei text,model text,storage_gb integer,color text,technician_name text,part_name text,quantity integer,status text,classification text,requested_at timestamptz,reviewed_at timestamptz,review_notes text,supplier_code text,batch_number text,invoice_number text,stock_received_at timestamptz)language sql stable security definer set search_path=pg_catalog,public as $$
 select r.*,b.batch_number::text,b.invoice_number::text,coalesce(b.received_at,j.received_at)from greenloop_private.psc_returns()r left join greenloop_private.parts_flow_orders o on o.id=r.order_id left join public.lab_part_return_requests lr on r.legacy and lr.id=r.id left join public.jobs j on j.id=coalesce(o.job_id,lr.job_id)left join public.receiving_batches b on b.id=j.receiving_batch_id;
$$;
create or replace function greenloop_private.sb_journey()returns jsonb language sql stable security definer set search_path=pg_catalog,public as $$
 select coalesce(jsonb_agg(v.value||jsonb_build_object('batch_number',b.batch_number)order by v.ord),'[]')from jsonb_array_elements(greenloop_private.filter_get_stock_journey_v1(null,null,'',0,100)->'rows')with ordinality v(value,ord)left join lateral(select j.receiving_batch_id from public.jobs j where j.device_id=(v.value->>'device_id')::uuid and j.deleted_at is null order by j.received_at desc,j.created_at desc,j.id desc limit 1)j on true left join public.receiving_batches b on b.id=j.receiving_batch_id;
$$;
create or replace function public.get_parts_batch_queue_v1(p_filters jsonb default '{}',p_offset integer default 0,p_limit integer default 50,p_sort_key text default 'submitted_at',p_sort_direction text default 'desc')returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare f date;t date;s text;st text;sc text;bn text;result jsonb;begin
 perform greenloop_private.pf_cap('parts','view');
 if jsonb_typeof(p_filters)is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_filters)k where k not in ('_search','_from','_to','status','supplier_code','batch_number'))or p_offset is null or p_offset<0 or p_limit is null or p_limit not between 1 and 100 or p_sort_key is null or p_sort_key not in ('submitted_at','imei','model','status','supplier_code','batch_number')or p_sort_direction is null or p_sort_direction not in ('asc','desc')then raise exception 'Select valid filters and sorting.'using errcode='22023';end if;
 if p_filters<>'{}'then perform greenloop_private.pf_cap('parts','search');end if;if p_sort_key<>'submitted_at' or p_sort_direction<>'desc'then perform greenloop_private.pf_cap('parts','sort');end if;
 f:=nullif(p_filters->>'_from','')::date;t:=nullif(p_filters->>'_to','')::date;s:=lower(btrim(coalesce(p_filters->>'_search','')));st:=nullif(p_filters->>'status','');sc:=nullif(p_filters->>'supplier_code','');bn:=nullif(p_filters->>'batch_number','');if f>t or length(s)>120 or length(sc)>120 or length(bn)>120 then raise exception 'Select valid dates or search.'using errcode='22023';end if;
 with base as materialized(select o.id order_id,o.revision,o.submitted_at,d.imei_1 imei,d.model,d.storage_gb,d.color,j.job_number,supplier.supplier_code,b.batch_number,b.invoice_number,coalesce(b.received_at,j.received_at)stock_received_at,greenloop_private.ps_status(o.id)status,coalesce((select s.assigned_technician_name from public.job_work_order_steps s where s.id=o.step_id),'Unassigned')technician_name,(select count(*)from public.job_part_requests r join greenloop_private.parts_flow_requests m on m.request_id=r.id where m.order_id=o.id and r.status<>'cancelled')parts_count from greenloop_private.parts_flow_orders o join public.jobs j on j.id=o.job_id and j.deleted_at is null join public.devices d on d.id=o.device_id and d.deleted_at is null left join public.suppliers supplier on supplier.id=j.supplier_id left join public.receiving_batches b on b.id=j.receiving_batch_id where greenloop_private.ps_has_parts(o.id)),q as materialized(select * from base where(f is null or(submitted_at at time zone 'Asia/Dubai')::date>=f)and(t is null or(submitted_at at time zone 'Asia/Dubai')::date<=t)and(s=''or strpos(lower(concat_ws(' ',imei,model,storage_gb,color,job_number,technician_name,supplier_code,batch_number,invoice_number)),s)>0)and(st is null or status=st)and(sc is null or supplier_code=sc)and(bn is null or batch_number=bn)),page as(select *from q order by case when p_sort_key='submitted_at'and p_sort_direction='asc'then submitted_at end asc,case when p_sort_key='submitted_at'and p_sort_direction='desc'then submitted_at end desc,case when p_sort_direction='asc'then case p_sort_key when 'imei'then imei when 'model'then model when 'status'then status when 'supplier_code'then supplier_code when 'batch_number'then batch_number end end asc,case when p_sort_direction='desc'then case p_sort_key when 'imei'then imei when 'model'then model when 'status'then status when 'supplier_code'then supplier_code when 'batch_number'then batch_number end end desc,order_id offset p_offset limit p_limit)
 select jsonb_build_object('total',(select count(*)from q),'rows',coalesce((select jsonb_agg(to_jsonb(p))from page p),'[]'),'facets',jsonb_build_object('status',(select coalesce(jsonb_agg(distinct status),'[]')from base),'supplier_code',(select coalesce(jsonb_agg(distinct supplier_code order by supplier_code),'[]')from base where supplier_code is not null),'batch_number',(select coalesce(jsonb_agg(distinct batch_number order by batch_number),'[]')from base where batch_number is not null)))into result;return result;
end;$$;
create or replace function public.get_parts_batch_returns_v1(p_filters jsonb default '{}',p_category text default 'pending',p_offset integer default 0,p_limit integer default 50,p_sort_key text default 'requested_at',p_sort_direction text default 'desc')returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare f date;t date;s text;sc text;bn text;result jsonb;begin
 perform greenloop_private.pf_cap('parts','view');if jsonb_typeof(p_filters)is distinct from 'object'or exists(select 1 from jsonb_object_keys(p_filters)k where k not in ('_search','_from','_to','supplier_code','batch_number'))or p_category is null or p_category not in ('pending','damaged','faulty','not_needed','other')or p_offset is null or p_offset<0 or p_limit is null or p_limit not between 1 and 100 or p_sort_key is null or p_sort_key not in ('requested_at','imei','model','part_name','quantity','supplier_code','batch_number')or p_sort_direction is null or p_sort_direction not in ('asc','desc')then raise exception 'Select valid return filters.'using errcode='22023';end if;
 if p_filters<>'{}'then perform greenloop_private.pf_cap('parts','search');end if;if p_sort_key<>'requested_at'or p_sort_direction<>'desc'then perform greenloop_private.pf_cap('parts','sort');end if;f:=nullif(p_filters->>'_from','')::date;t:=nullif(p_filters->>'_to','')::date;s:=lower(btrim(coalesce(p_filters->>'_search','')));sc:=nullif(p_filters->>'supplier_code','');bn:=nullif(p_filters->>'batch_number','');if f>t or length(s)>120 or length(sc)>120 or length(bn)>120 then raise exception 'Select valid dates or search.'using errcode='22023';end if;
 with source as materialized(select *from greenloop_private.sb_returns()),base as materialized(select *from source where(sc is null or supplier_code=sc)and(bn is null or batch_number=bn)and(f is null or(requested_at at time zone 'Asia/Dubai')::date>=f)and(t is null or(requested_at at time zone 'Asia/Dubai')::date<=t)and(s=''or strpos(lower(concat_ws(' ',imei,model,storage_gb,color,technician_name,part_name,review_notes,supplier_code,batch_number,invoice_number)),s)>0)),q as materialized(select *from base where case when p_category='pending'then status='pending'else status='approved'and classification=p_category end),page as(select *from q order by case when p_sort_key='requested_at'and p_sort_direction='asc'then requested_at end asc,case when p_sort_key='requested_at'and p_sort_direction='desc'then requested_at end desc,case when p_sort_key='quantity'and p_sort_direction='asc'then quantity end asc,case when p_sort_key='quantity'and p_sort_direction='desc'then quantity end desc,case when p_sort_direction='asc'then case p_sort_key when 'imei'then imei when 'model'then model when 'part_name'then part_name when 'supplier_code'then supplier_code when 'batch_number'then batch_number end end asc,case when p_sort_direction='desc'then case p_sort_key when 'imei'then imei when 'model'then model when 'part_name'then part_name when 'supplier_code'then supplier_code when 'batch_number'then batch_number end end desc,id offset p_offset limit p_limit)
 select jsonb_build_object('total',(select count(*)from q),'rows',coalesce((select jsonb_agg(to_jsonb(p))from page p),'[]'),'counts',(select jsonb_build_object('pending',count(*)filter(where status='pending'),'damaged',coalesce(sum(quantity)filter(where status='approved'and classification='damaged'),0),'faulty',coalesce(sum(quantity)filter(where status='approved'and classification='faulty'),0),'not_needed',coalesce(sum(quantity)filter(where status='approved'and classification='not_needed'),0),'other',coalesce(sum(quantity)filter(where status='approved'and classification='other'),0))from base),'facets',jsonb_build_object('supplier_code',(select coalesce(jsonb_agg(distinct supplier_code order by supplier_code),'[]')from source where supplier_code is not null),'batch_number',(select coalesce(jsonb_agg(distinct batch_number order by batch_number),'[]')from source where batch_number is not null)))into result;return result;
end;$$;
create or replace function public.get_parts_batch_order_v1(p_order_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare result jsonb;receipt jsonb;begin
 perform greenloop_private.pf_cap('parts','view');result:=public.get_parts_supplier_order_v1(p_order_id);select jsonb_build_object('batch_number',b.batch_number,'invoice_number',b.invoice_number,'stock_received_at',coalesce(b.received_at,j.received_at))into receipt from greenloop_private.parts_flow_orders o join public.jobs j on j.id=o.job_id left join public.receiving_batches b on b.id=j.receiving_batch_id where o.id=p_order_id;return jsonb_set(result,'{device}',(result->'device')||receipt);
end;$$;
create or replace function public.get_stock_batch_report_v1(p_source text,p_filters jsonb default '{}',p_offset integer default 0,p_limit integer default 50,p_sort_by text default null,p_sort_direction text default 'asc')
returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare source_rows jsonb;matched jsonb;keys text[];facet_keys text[];date_key text;v_page_key text;facets jsonb;result jsonb;metadata jsonb;sort_keys text[];number_keys text[];date_keys text[];sort_type text;
begin
 if p_source is null or p_source not in ('journey','accounts_supplier','accounts_customer')then raise exception 'Choose a stock batch report.'using errcode='22023';end if;
 if p_source is null or jsonb_typeof(p_filters) is distinct from 'object' or octet_length(p_filters::text)>5000 or p_offset is null or p_offset<0 or p_limit is null or p_limit<1 or p_limit>200 then raise exception 'Invalid table filters or page.' using errcode='22023';end if;
 if nullif(p_filters->>'_from','')::date>nullif(p_filters->>'_to','')::date then raise exception 'From date must be on or before To date.' using errcode='22023';end if;
 v_page_key:=case p_source when 'inventory_receipts' then 'inventory' when 'part_returns' then 'parts' when 'frame_results' then 'frame_department' when 'journey' then 'ready_stock_journey' when 'accounts_supplier' then 'accounts' when 'accounts_customer' then 'accounts' when 'accounts' then 'accounts' when 'stock_exported' then 'stock_exported' when 'damage_entry' then 'tv_manual_entry' when 'damage_management' then 'reports' end;
 if v_page_key is null then raise exception 'Unknown filter source.' using errcode='22023';end if;perform greenloop_private.pf_cap(v_page_key,'view');if exists(select 1 from jsonb_each_text(p_filters)where coalesce(value,'')<>'')then perform greenloop_private.pf_cap(v_page_key,'search');end if;if p_sort_by is not null then perform greenloop_private.pf_cap(v_page_key,'sort');end if;
 if auth.uid() is null or not coalesce(public.is_active_staff(),false) or not coalesce(
 (select access_level in ('view','edit') from public.user_page_permissions where user_id=auth.uid() and user_page_permissions.page_key=v_page_key),
 public.has_role(array['owner','super_admin']::public.app_role_key[]),false) then raise exception 'Page view permission is required.' using errcode='42501';end if;
 case p_source
 when 'journey' then
  source_rows:=greenloop_private.sb_journey();
  keys:=array['imei','device_number','device_details','current_stage','current_status','supplier_code','supplier_company','invoice_number','batch_number','technician_name','box_number','customer_name','company_final_grade'];facet_keys:=array['current_stage','supplier_code','batch_number','company_final_grade'];date_key:='date_entered';
 when 'accounts_supplier','accounts_customer' then
  source_rows:=greenloop_private.filter_get_accounts_stock_v1(case when p_source='accounts_supplier' then 'supplier' else 'customer' end,null,null,null,0,100)->'rows';
  keys:=array['supplier_code','supplier_name','customer_code','customer_name','invoice_number','batch_number','box_number','model','storage_gb','color','final_grade'];facet_keys:=array['supplier_code','batch_number','customer_code','model','storage_gb','color','final_grade'];date_key:=case when p_source='accounts_supplier' then 'received_at' else 'exported_at' end;
 else raise exception 'Choose a stock batch report.'using errcode='22023';
 end case;

 -- Only typed, visible fields may control ordering. Filtering and privacy run first.
 number_keys:=array['quantity','quantity_received','total_cost','unit_cost','storage_gb','received','in_company','ready','in_process','exported','returned','awaiting_imei','price_amount','total_value','parts_cost'];
 date_keys:=array['received_at','returned_at','reviewed_at','date_entered','date_received','date_completed','export_date','exported_at','saved_at','verified_at','filter_date','occurred_at','created_at'];
 sort_keys:=keys||array[date_key]||case p_source
 when 'inventory_receipts' then array['quantity_received','total_cost','unit_cost']
 when 'part_returns' then array['quantity']
 when 'journey' then array['date_received','date_completed','export_date','parts_cost','quantity_received','stock_channel','battery_health','supplier_grade','company_initial_grade','parts_issued','service_done']
 when 'accounts_supplier' then array['received','in_company','ready','in_process','exported','returned','awaiting_imei']
 when 'accounts_customer' then array['received_at','quantity']
 when 'accounts' then array['saved_at','verified_at','quantity']
 when 'stock_exported' then array['saved_at','verified_at','quantity']
 when 'damage_entry' then array['quantity','price_amount','total_value','created_at']
 when 'damage_management' then array['quantity','price_amount','total_value','created_at']
 else array[]::text[] end;
 if p_sort_direction is null or p_sort_direction not in ('asc','desc') or (p_sort_by is not null and not p_sort_by=any(sort_keys)) then raise exception 'Invalid sort field or direction.' using errcode='22023';end if;
 sort_type:=case when p_sort_by=any(number_keys) then 'number' when p_sort_by=any(date_keys) then 'date' else 'text' end;
 if p_source in ('damage_entry','damage_management') then
  select coalesce(jsonb_agg(value||jsonb_build_object('total_value',nullif(value->>'price_amount','')::numeric*coalesce(nullif(value->>'quantity','')::numeric,1)) order by ord),'[]') into source_rows from jsonb_array_elements(source_rows) with ordinality r(value,ord);
 end if;
 if exists(select 1 from jsonb_object_keys(p_filters) k where not k=any(keys||array['_from','_to','_search'])) then raise exception 'Unknown filter field.' using errcode='22023';end if;
 select coalesce(jsonb_object_agg(k,values),'{}') into facets from (select k,(select coalesce(jsonb_agg(v order by v),'[]') from (select distinct value->>k v from jsonb_array_elements(source_rows) where nullif(value->>k,'') is not null) vals) values from unnest(facet_keys) k) f;
 select coalesce(jsonb_agg(value order by ord),'[]') into matched from jsonb_array_elements(source_rows) with ordinality r(value,ord) where greenloop_private.filter_record_matches(value,p_filters,keys,date_key);

 -- Sort the whole matching array before taking a page; missing values stay last.
 -- Original ordinal is the final tiebreaker so equal values remain stable.
 if p_sort_by is not null then
  select coalesce(jsonb_agg(value order by
   case when sort_type='number' and p_sort_direction='asc' then nullif(value->>p_sort_by,'')::numeric end asc nulls last,
   case when sort_type='number' and p_sort_direction='desc' then nullif(value->>p_sort_by,'')::numeric end desc nulls last,
   case when sort_type='date' and p_sort_direction='asc' then nullif(value->>p_sort_by,'')::timestamptz end asc nulls last,
   case when sort_type='date' and p_sort_direction='desc' then nullif(value->>p_sort_by,'')::timestamptz end desc nulls last,
   case when sort_type='text' and p_sort_direction='asc' then lower(nullif(btrim(value->>p_sort_by),'')) end asc nulls last,
   case when sort_type='text' and p_sort_direction='desc' then lower(nullif(btrim(value->>p_sort_by),'')) end desc nulls last,
   ord),'[]') into matched from jsonb_array_elements(matched) with ordinality r(value,ord);
 end if;
 select jsonb_build_object('total',jsonb_array_length(matched),'record_count',jsonb_array_length(matched),'total_count',jsonb_array_length(matched),'has_more',p_offset::bigint+p_limit<jsonb_array_length(matched),'facets',facets,
 'rows',coalesce((select jsonb_agg(value order by ord) from (select value,ord from jsonb_array_elements(matched) with ordinality r(value,ord) order by ord offset p_offset limit p_limit) paged),'[]'),
 'totals',jsonb_build_object(
 'received',coalesce((select sum((r->>'received')::numeric) from jsonb_array_elements(matched) r),0),
 'in_company',coalesce((select sum((r->>'in_company')::numeric) from jsonb_array_elements(matched) r),0),
 'ready',coalesce((select sum((r->>'ready')::numeric) from jsonb_array_elements(matched) r),0),
 'in_process',coalesce((select sum((r->>'in_process')::numeric) from jsonb_array_elements(matched) r),0),
 'exported',coalesce((select sum(coalesce(r->>'exported',r->>'quantity')::numeric) from jsonb_array_elements(matched) r),0),
 'returned',coalesce((select sum((r->>'returned')::numeric) from jsonb_array_elements(matched) r),0),
 'quantity',coalesce((select sum(coalesce(r->>'quantity',r->>'quantity_received','0')::numeric) from jsonb_array_elements(matched) r),0),
 'total_cost',coalesce((select sum((r->>'total_cost')::numeric) from jsonb_array_elements(matched) r),0),
 'total_value',coalesce((select sum((r->>'total_value')::numeric) from jsonb_array_elements(matched) r),0),
 'pass',(select count(*) from jsonb_array_elements(matched) r where r->>'result'='pass'),
 'fail',(select count(*) from jsonb_array_elements(matched) r where r->>'result'='fail')
 )) into result;
 return coalesce(metadata,'{}'::jsonb)||result;
end; $$;
