insert into greenloop_private.capability_rpc_rules values('get_parts_batch_returns_v1','{"page":"parts","capability":"view","read":true}'::jsonb)on conflict(rpc_name)do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('get_parts_batch_order_v1','{"page":"parts","capability":"view","read":true}'::jsonb)on conflict(rpc_name)do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('get_stock_batch_report_v1','{"any":[{"page":"accounts","capability":"view","read":true},{"page":"ready_stock_journey","capability":"view","read":true}],"read":true}'::jsonb)on conflict(rpc_name)do update set rule=excluded.rule;
update greenloop_private.page_capability_installation set hash=(select md5(jsonb_agg(to_jsonb(r)order by rpc_name)::text)from greenloop_private.capability_rpc_rules r)where identity='rules';
do $wrap$declare f record;impl text;impl_identity text;args text;body text;begin
 for f in select p.*,pg_get_functiondef(p.oid)ddl,p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('get_parts_batch_queue_v1','get_parts_batch_returns_v1','get_parts_batch_order_v1','get_stock_batch_report_v1')loop
 impl:='office_impl_'||f.oid;execute regexp_replace(f.ddl,'FUNCTION public\.'||f.proname||'\(','FUNCTION greenloop_private.'||impl||'(');impl_identity:='greenloop_private.'||impl||'('||oidvectortypes(f.proargtypes)||')';execute format('revoke all on function %s from public,anon,authenticated',impl_identity);select coalesce(string_agg('$'||i,','order by i),'')into args from generate_series(1,f.pronargs)i;
 body:=E'begin\n -- greenloop-office-wrapper-196\n perform greenloop_private.require_office_network();\n return greenloop_private.'||impl||'('||args||E');\nend;';execute format('create or replace function public.%I(%s)returns %s language plpgsql %s security definer set search_path=pg_catalog,public as %L',f.proname,pg_get_function_arguments(f.oid),pg_get_function_result(f.oid),case f.provolatile when 's'then 'stable'else 'volatile'end,body);execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to authenticated',f.signature);insert into greenloop_private.office_routines values(f.signature,impl_identity,md5(pg_get_functiondef(impl_identity::regprocedure)),md5(pg_get_functiondef(f.oid)))on conflict(identity)do update set implementation=excluded.implementation,original_hash=excluded.original_hash,wrapped_hash=excluded.wrapped_hash;
 end loop;for f in select p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='greenloop_private'::regnamespace and p.proname in ('sb_returns','sb_journey')loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);end loop;
end;$wrap$;
create table if not exists greenloop_private.stock_batch_links_installation(identity text primary key,hash text not null);
alter table greenloop_private.stock_batch_links_installation enable row level security;revoke all on greenloop_private.stock_batch_links_installation from public,anon,authenticated;
insert into greenloop_private.stock_batch_links_installation select p.oid::regprocedure::text,md5(pg_get_functiondef(p.oid))from pg_proc p where(p.pronamespace='public'::regnamespace and p.proname in ('get_parts_batch_queue_v1','get_parts_batch_returns_v1','get_parts_batch_order_v1','get_stock_batch_report_v1'))or(p.pronamespace='greenloop_private'::regnamespace and p.proname in ('sb_returns','sb_journey'))on conflict(identity)do update set hash=excluded.hash;
create or replace function public.get_stock_batch_links_version()returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when public.get_parts_supplier_codes_version()='20261027-parts-supplier-codes-1'
 and(select count(*)=6 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.stock_batch_links_installation)
 and not has_table_privilege('authenticated','greenloop_private.stock_batch_links_installation','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')and not has_table_privilege('anon','greenloop_private.stock_batch_links_installation','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')
 and not exists(select 1 from greenloop_private.stock_batch_links_installation where identity like 'greenloop_private.%'and(has_function_privilege('authenticated',to_regprocedure(identity),'EXECUTE')or has_function_privilege('anon',to_regprocedure(identity),'EXECUTE')))
 then '20261027-stock-batches-1'end;$$;
revoke all on function public.get_stock_batch_links_version()from public;grant execute on function public.get_stock_batch_links_version()to anon,authenticated;
do $$begin if public.get_stock_batch_links_version()is distinct from '20261027-stock-batches-1'then raise exception 'Stock batch links verification failed.';end if;end;$$;
notify pgrst,'reload schema';commit;
select public.get_stock_batch_links_version()as installed_stock_batch_links_version;
